	return a > b;
}

int main(){
	scanf("%d", &t);
	while(t--){
		hmap.clear();
		scanf("%d%d", &n, &k);
		for(int i = 1; i <= n; i++) {
			scanf("%d", &a[i]);
			if(hmap.count(a[i]) == 0) hmap[a[i]] = 1;
			else hmap[a[i]]++;
		}
		sort(a + 1, a + n + 1, cmp);
		n = unique(a + 1, a + n + 1) - a - 1;
		//printf("n = %d\n", n);
		int ans = 0;
		while(k){
			ans = 0;
			for(int i = 1; i <= n && k; i++){
				if(hmap[a[i]]) {
					ans = max(ans, a[i]);
					k--;
					hmap[a[i]]--;
				}
			}
		}
		printf("%d\n", ans);
	}
	return 0;
}
