#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n, k;
        cin >> n >> k;
        vector<int> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i];

        // 统计频率
        unordered_map<int, int> freq;
        for (int x : a) freq[x]++;

        // 存储（频率, 流派编号）对
        vector<pair<int, int>> v;
        for (auto &p : freq) {
            v.emplace_back(p.second, p.first);
        }

        // 按频率升序排序
        sort(v.begin(), v.end(),
             [](const pair<int, int>& x, const pair<int, int>& y) {
                 return x.first < y.first;
             });

        long long t = 0;         // 已确定可选入的歌曲总数
        int res = 0;
        int cnt = v.size();      // 剩余未处理的流派数

        for (auto &p : v) {
            int L = p.first;
            int R = p.second;
            cnt--;
            if (L + t + 1LL * cnt * L >= k) {
                res = max(res, R);
            }
            t += L;
        }

        cout << res << "\n";
    }

    return 0;
}
